package com.vandorlabs.neoforge.light;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import java.lang.management.ManagementFactory;
import java.util.concurrent.CompletableFuture;
/** Actual prepared worlds and worker reads; no source geometry is reconstructed by the renderer. */
public final class LightProjectionHostChecks {
 private static int checks;private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Light projection host: "+why);}
 private static void bounded(NativeLightEntity source){var world=(ServerLevel)source.getLevel();var base=source.getBlockPos().east(128);var state=source.getBlockState();var tag=new net.minecraft.nbt.CompoundTag();tag.putBoolean("LightJoin",true);tag.putBoolean("LightOn",true);tag.putInt("LightLevel",0);tag.putInt("LightTrigger",0);NativeLightEntity root=null;for(int n=0;n<4095;n++){var pos=base.offset(n%64,n/64,0);world.getChunkAt(pos);world.setBlock(pos,state,18);var owner=(NativeLightEntity)world.getBlockEntity(pos);owner.loadWithComponents(tag,world.registryAccess());if(n==0)root=owner;}long start=System.nanoTime();NativeLightService.refresh(root);long elapsed=(System.nanoTime()-start)/1000000;need(elapsed<15000,"4095-member actual host preparation remains bounded ms="+elapsed);need(root.renderProjection().right()==16D/64&&root.renderProjection().top()==16D*62/63,"4095-member irregular rectangle uses released largest-first partition");var retained=root.renderPublication();var model=root.getModelData();for(int n=0;n<10000;n++)if(root.renderPublication()!=retained||root.getModelData()!=model)throw new AssertionError("Large joined Light publication is not reused");for(int n=0;n<4095;n++)world.setBlock(base.offset(n%64,n/64,0),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),18);NativeLightService.flush(world);System.out.println("[vandorlabs][light-projection-host] bound PASS members=4095 elapsedMs="+elapsed+" cachedReads=10000");}
 public static void run(NativeLightEntity first,NativeLightEntity second)throws Exception{var world=(ServerLevel)first.getLevel();var pos=first.getBlockPos();var initial=first.renderPublication();need(initial.visual()==first.visual()&&initial.projection().left()==0&&initial.projection().right()==8&&second.renderProjection().left()==8&&second.renderProjection().right()==16,"atomic two-column source artwork");need(initial.projection().visibleFaces()==31&&second.renderProjection().visibleFaces()==47,"source exact local shared-face culling");var model=first.getModelData();need(model.get(NativeLightEntity.VISUAL)==initial.visual()&&model.get(NativeLightEntity.PROJECTION)==initial.projection(),"worker model data captures same atomic publication");long before=first.renderPublications();for(int n=0;n<20;n++)NativeLightService.refresh(first);need(first.renderPublication()==initial&&first.getModelData()==model&&first.renderPublications()==before,"unchanged loaded updates retain pair and model data identity");
  long allocated=CompletableFuture.supplyAsync(()->{var bean=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);for(int n=0;n<10000;n++)if(first.getModelData()!=model||first.renderPublication()!=initial)throw new AssertionError("Unstable Light worker warmup");long id=Thread.currentThread().threadId(),start=bean.getThreadAllocatedBytes(id);for(int n=0;n<100000;n++)if(first.getModelData()!=model||first.renderPublication()!=initial)throw new AssertionError("Unstable Light worker snapshot");return bean.getThreadAllocatedBytes(id)-start;}).get();need(allocated==0,"100000 worker projection/model reads allocate zero bytes actual="+allocated);
  var old=second.getBlockState();world.setBlock(second.getBlockPos(),old.setValue(NativeLightBlock.FACING,Direction.SOUTH),18);NativeLightService.refresh(first);need(first.renderProjection().left()==0&&first.renderProjection().right()==16&&first.renderProjection().visibleFaces()==31,"facing mismatch splits UV without exposing fully covered same-block face");world.setBlock(second.getBlockPos(),old,18);NativeLightService.refresh(first);need(first.renderProjection().right()==8&&second.renderProjection().left()==8,"changed facing rejoins before observer publication");
  var above=pos.above();world.setBlock(above,old,18);var third=(NativeLightEntity)world.getBlockEntity(above);var tag=first.itemSettings();third.loadWithComponents(tag,world.registryAccess());third.onLoad();NativeLightService.refresh(first);need(first.renderProjection().right()==8&&third.renderProjection().left()==0&&third.renderProjection().right()==16,"irregular L partitions largest horizontal rectangle then singleton");world.removeBlock(above,false);NativeLightService.refresh(first);need(first.renderProjection().right()==8,"removing irregular member restores stable paired UV");
  var previous=first.renderPublication();var edit=new net.minecraft.nbt.CompoundTag();edit.putInt("NativeLightSchema",99);third=new NativeLightEntity(first.getType(),above,old,com.vandorlabs.neoforge.screen.NativeScreenCatalog.INSTANCE);third.loadWithComponents(edit,world.registryAccess());need(third.renderPublication().visual()==third.visual()&&third.renderProjection()==NativeLightRenderProjection.SINGLE,"unbound inert recovery publication stays self-contained");need(previous.visual()==first.visual(),"retained publication contains no mutable member collection");bounded(first);System.out.println("[vandorlabs][light-projection-host] PASS checks="+checks+" workerReads=100000 allocatedBytes="+allocated);}
}
